/**
 * Simple Harmonic Motion simulation (a mass on a spring, released from rest
 * at amplitude A).
 *
 * omega = 2*pi / period
 * x(t) = A*cos(omega*t)
 * v(t) = -A*omega*sin(omega*t)
 * a(t) = -omega^2 * x(t)
 *
 * Always computed here, in code -- never fetched from a server and never
 * generated by AI. Mirrors apps/physics/simulations_shm.py exactly (same
 * bounds, same formulas), the same way circular-motion.js mirrors
 * simulations_circular_motion.py. This file owns its own physics, SVG and
 * controls; it shares only the run-loop/registry shell in lab.js.
 */
(function (window, document) {
  "use strict";

  var MIN_AMPLITUDE_M = 0.1;
  var MAX_AMPLITUDE_M = 2.0;
  var MIN_PERIOD_S = 0.5;
  var MAX_PERIOD_S = 10.0;
  var MAX_TIME_S = 40.0;

  function clampAmplitude(value) {
    var n = Number(value);
    if (!isFinite(n)) return NaN;
    return Math.max(MIN_AMPLITUDE_M, Math.min(MAX_AMPLITUDE_M, n));
  }
  function clampPeriod(value) {
    var n = Number(value);
    if (!isFinite(n)) return NaN;
    return Math.max(MIN_PERIOD_S, Math.min(MAX_PERIOD_S, n));
  }

  function computeState(amplitude, period, t) {
    amplitude = clampAmplitude(amplitude);
    period = clampPeriod(period);
    t = Math.max(0, Math.min(MAX_TIME_S, Number(t)));
    var omega = (2 * Math.PI) / period;
    var x = amplitude * Math.cos(omega * t);
    var v = -amplitude * omega * Math.sin(omega * t);
    var accel = -omega * omega * x;
    return { x: x, v: v, a: accel };
  }

  // Geometry constants for the SVG scene/graph.
  var CENTER_X_PX = 200;
  var TRACK_Y_PX = 140;
  var USABLE_HALF_WIDTH_PX = 150;
  var STEP_S = 0.05;
  var REDUCED_MOTION_STOP_S = 6;

  function readNum(el, name, fallback) {
    var raw = el.getAttribute("data-" + name);
    var value = parseFloat(raw);
    return isFinite(value) ? value : fallback;
  }
  function round4(n) {
    return Math.round(n * 10000) / 10000;
  }

  function createShmSim(root, config, lab) {
    var state = {
      amplitude: clampAmplitude(readNum(root, "amplitude", 1)),
      period: clampPeriod(readNum(root, "period", 2)),
      timeS: 0,
      x: 0,
      v: 0,
      a: 0,
      scale: 10
    };

    var trace = []; // [t, x] samples, feeds the x-vs-time graph
    var maxAbsX = 1;

    var el = {
      scene: root.querySelector("[data-lab-scene]"),
      sceneDesc: root.querySelector("[data-scene-desc]"),
      marker: root.querySelector("[data-cart]"),
      spring: root.querySelector("[data-spring-line]"),
      sceneStatus: root.querySelector("[data-scene-status]"),
      graph: root.querySelector("[data-lab-graph]"),
      graphDesc: root.querySelector("[data-graph-desc]"),
      trace: root.querySelector("[data-lab-trace]"),
      valueAmplitude: root.querySelector("[data-value-amplitude]"),
      valuePeriod: root.querySelector("[data-value-period]"),
      valueTime: root.querySelector("[data-value-time]"),
      valuePosition: root.querySelector("[data-value-position]"),
      valueVelocity: root.querySelector("[data-value-velocity]"),
      valueAccel: root.querySelector("[data-value-accel]"),
      eqPosition: root.querySelector("[data-eq-position]"),
      eqAccel: root.querySelector("[data-eq-accel]"),
      outAmplitude: root.querySelector("[data-out-amplitude]"),
      outPeriod: root.querySelector("[data-out-period]"),
      inputAmplitude: root.querySelector("[data-input-amplitude]"),
      inputPeriod: root.querySelector("[data-input-period]"),
      btnStart: root.querySelector("[data-action-start]"),
      btnPause: root.querySelector("[data-action-pause]"),
      btnReset: root.querySelector("[data-action-reset]"),
      btnStep: root.querySelector("[data-action-step]"),
      inputTime: root.querySelector("[data-input-time]"),
      outTime: root.querySelector("[data-out-time]"),
      motionNote: root.querySelector("[data-motion-note]")
    };

    var loop = lab.createRunLoop(tick, {});

    function updateScale() {
      state.scale = USABLE_HALF_WIDTH_PX / state.amplitude;
    }
    function screenX(xM) {
      return CENTER_X_PX + xM * state.scale;
    }

    function recordTrace() {
      trace.push([round4(state.timeS), round4(state.x)]);
      maxAbsX = Math.max(maxAbsX, Math.abs(state.x));
      if (trace.length > 2000) trace.shift();
    }

    function setAmplitude(value) {
      state.amplitude = clampAmplitude(value);
      if (el.inputAmplitude) el.inputAmplitude.value = String(state.amplitude);
      if (el.outAmplitude) el.outAmplitude.textContent = String(state.amplitude);
      updateScale();
      setTime(0);
    }
    function setPeriod(value) {
      state.period = clampPeriod(value);
      if (el.inputPeriod) el.inputPeriod.value = String(state.period);
      if (el.outPeriod) el.outPeriod.textContent = String(state.period);
      setTime(0);
    }

    function start() {
      loop.start();
    }
    function pause() {
      loop.stop();
    }
    function reset() {
      loop.stop();
      setTime(0);
    }

    function rebuildTrace(upToT) {
      trace = [];
      maxAbsX = Math.max(1, state.amplitude);
      var sampleDt = Math.max(upToT / 60, 0.02);
      for (var t = 0; t < upToT - 1e-9; t += sampleDt) {
        var c = computeState(state.amplitude, state.period, t);
        trace.push([round4(t), round4(c.x)]);
      }
      trace.push([round4(upToT), round4(state.x)]);
    }

    function setTime(value) {
      loop.stop();
      var t = Number(value);
      if (!isFinite(t)) return;
      t = Math.max(0, Math.min(MAX_TIME_S, t));
      var computed = computeState(state.amplitude, state.period, t);
      state.timeS = t;
      state.x = computed.x;
      state.v = computed.v;
      state.a = computed.a;
      rebuildTrace(t);
      if (el.sceneStatus) el.sceneStatus.textContent = "";
      render();
    }

    function stepForward() {
      setTime(state.timeS + STEP_S);
    }

    function tick(dt) {
      if (state.timeS >= MAX_TIME_S) {
        loop.stop();
        if (el.sceneStatus) {
          el.sceneStatus.textContent = "Reached the end of the simulated time window (40 s).";
        }
        return;
      }
      var nextT = Math.min(MAX_TIME_S, state.timeS + dt);
      var computed = computeState(state.amplitude, state.period, nextT);
      state.timeS = nextT;
      state.x = computed.x;
      state.v = computed.v;
      state.a = computed.a;
      recordTrace();

      if (loop.reduced && state.timeS >= REDUCED_MOTION_STOP_S) {
        loop.stop();
      }
      render();
    }

    function renderScene() {
      if (el.marker) {
        el.marker.setAttribute("transform", "translate(" + screenX(state.x).toFixed(1) + "," + TRACK_Y_PX + ")");
      }
      if (el.spring) {
        el.spring.setAttribute("x1", String(CENTER_X_PX - USABLE_HALF_WIDTH_PX - 40));
        el.spring.setAttribute("y1", String(TRACK_Y_PX));
        el.spring.setAttribute("x2", screenX(state.x).toFixed(1));
        el.spring.setAttribute("y2", String(TRACK_Y_PX));
      }
      var text =
        "A mass oscillating on a spring with amplitude " + state.amplitude.toFixed(2) +
        " metres and period " + state.period.toFixed(1) + " seconds. At " +
        state.timeS.toFixed(1) + " seconds it is at " + state.x.toFixed(2) +
        " metres from the centre, moving at " + state.v.toFixed(2) + " metres per second.";
      if (el.scene) el.scene.setAttribute("aria-label", text);
      if (el.sceneDesc) el.sceneDesc.textContent = text;
    }

    function renderGraph() {
      if (!el.trace) return;
      var w = 348, h = 156, left = 40, top = 10, bottom = 6;
      var tMin = trace.length ? trace[0][0] : 0;
      var tMax = Math.max(tMin + 1, state.timeS);
      var xMax = Math.max(1, maxAbsX);
      var points = [];
      for (var i = 0; i < trace.length; i++) {
        var px = left + ((trace[i][0] - tMin) / (tMax - tMin)) * (w - left - 12);
        var py = h - bottom - ((trace[i][1] + xMax) / (2 * xMax)) * (h - top - bottom);
        points.push(px.toFixed(1) + "," + py.toFixed(1));
      }
      el.trace.setAttribute("points", points.join(" "));
      var graphText =
        "Position vs time. At " + state.timeS.toFixed(1) + " seconds the position is " +
        state.x.toFixed(2) + " metres.";
      if (el.graph) el.graph.setAttribute("aria-label", graphText);
      if (el.graphDesc) el.graphDesc.textContent = graphText;
    }

    function render() {
      if (el.valueAmplitude) el.valueAmplitude.textContent = String(state.amplitude);
      if (el.valuePeriod) el.valuePeriod.textContent = String(state.period);
      if (el.valueTime) el.valueTime.textContent = state.timeS.toFixed(2);
      if (el.valuePosition) el.valuePosition.textContent = state.x.toFixed(2);
      if (el.valueVelocity) el.valueVelocity.textContent = state.v.toFixed(2);
      if (el.valueAccel) el.valueAccel.textContent = state.a.toFixed(2);
      if (el.eqPosition) el.eqPosition.textContent = state.x.toFixed(2);
      if (el.eqAccel) el.eqAccel.textContent = state.a.toFixed(2);
      if (el.inputTime && document.activeElement !== el.inputTime) {
        el.inputTime.value = String(round4(state.timeS));
      }
      if (el.outTime) el.outTime.textContent = state.timeS.toFixed(1);
      renderScene();
      renderGraph();
      root.dispatchEvent(new CustomEvent("lab:state", { detail: getState() }));
    }

    function getState() {
      return {
        amplitudeM: state.amplitude,
        periodS: state.period,
        timeS: state.timeS,
        positionM: state.x,
        velocityMs: state.v,
        accelerationMs2: state.a,
        running: loop.isRunning()
      };
    }

    if (el.inputAmplitude) {
      el.inputAmplitude.addEventListener("input", function () { setAmplitude(el.inputAmplitude.value); });
      el.inputAmplitude.addEventListener("change", function () { setAmplitude(el.inputAmplitude.value); });
    }
    if (el.inputPeriod) {
      el.inputPeriod.addEventListener("input", function () { setPeriod(el.inputPeriod.value); });
      el.inputPeriod.addEventListener("change", function () { setPeriod(el.inputPeriod.value); });
    }
    if (el.btnStart) el.btnStart.addEventListener("click", start);
    if (el.btnPause) el.btnPause.addEventListener("click", pause);
    if (el.btnReset) el.btnReset.addEventListener("click", reset);
    if (el.btnStep) el.btnStep.addEventListener("click", stepForward);
    if (el.inputTime) {
      el.inputTime.addEventListener("input", function () { setTime(el.inputTime.value); });
      el.inputTime.addEventListener("change", function () { setTime(el.inputTime.value); });
    }

    if (loop.reduced && el.motionNote) el.motionNote.hidden = false;

    updateScale();
    reset();

    var api = {
      setAmplitude: setAmplitude,
      setPeriod: setPeriod,
      start: start,
      pause: pause,
      reset: reset,
      setTime: setTime,
      step: stepForward,
      getState: getState
    };
    root.labInstance = api;
    return api;
  }

  PhysicsLab.register("simple_harmonic_motion", createShmSim);

  PhysicsLab.SHM = {
    MIN_AMPLITUDE_M: MIN_AMPLITUDE_M,
    MAX_AMPLITUDE_M: MAX_AMPLITUDE_M,
    MIN_PERIOD_S: MIN_PERIOD_S,
    MAX_PERIOD_S: MAX_PERIOD_S,
    MAX_TIME_S: MAX_TIME_S,
    clampAmplitude: clampAmplitude,
    clampPeriod: clampPeriod,
    computeState: computeState
  };
})(window, document);
